namespace ghidra.util;




public class MergeSortingSpliterator<T> : Spliterator<T> {
	static class SpliteratorEntry<T> {
		Spliterator<T> spliterator;
		T next;
		bool hasNext;

		SpliteratorEntry(Spliterator<T> spliterator) {
			this.spliterator = spliterator;
			tryNext();
		}

		bool tryNext() {
			return hasNext = spliterator.tryAdvance(n => next = n);
		}
	}

	private Comparator<T> comparator;
	private PriorityQueue<SpliteratorEntry<T>> queue;

	public MergeSortingSpliterator(Iterable<Spliterator<? extends T>> spliterators,
			Comparator<T> comparator) {
		this.comparator = comparator;
		this.queue = new(Comparator.comparing(se => se.next, comparator));
		foreach (Spliterator<T> s in spliterators) {
			SpliteratorEntry<T> se = new(s);
			if (se.hasNext) {
				queue.add(se);
			}
		}
	}

	/* @Override */
	public bool tryAdvance(Consumer<T> action) {
		SpliteratorEntry<T> se = queue.poll();
		if (se == null) {
			return false;
		}
		T next = se.next;
		if (se.tryNext()) {
			queue.add(se);
		}
		action.accept(next);
		return true;
	}

	/* @Override */
	public Spliterator<T> trySplit() {
		return null;
	}

	/* @Override */
	public long estimateSize() {
		return queue.stream().mapToLong(se => se.spliterator.estimateSize()).sum() +
			queue.size();
	}

	/* @Override */
	public int characteristics() {
		return Spliterator.ORDERED | Spliterator.SORTED;
	}

	/* @Override */
	public Comparator<T> getComparator() {
		return comparator;
	}
}
